def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        bid = min(budget, DAILY_SALARY * 0.35)
        return float(max(0.0, bid))

    prev_bids = []
    bob_bid = None
    cindy_bid = None
    max_prev = 0.0
    for agent_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        bid_val = prev.get('bid')
        if bid_val is not None:
            bid_val = float(bid_val)
            prev_bids.append(bid_val)
            if bid_val > max_prev:
                max_prev = bid_val
            if agent_id == 'Bob':
                bob_bid = bid_val
            if agent_id == 'Cindy':
                cindy_bid = bid_val

    units = int(supply // WATER_REQ)
    urgent = (hp <= 4) or (no_water_days >= 2)
    very_urgent = (hp <= 2) or (no_water_days >= 3)

    if bob_bid is None:
        bob_bid = 60.0
    if cindy_bid is None:
        cindy_bid = 147.0

    alive_count = len(alive)
    likely_cindy_alive = False
    for agent_id, opp in opponents_status.items():
        if agent_id == 'Cindy' and opp.get('alive'):
            likely_cindy_alive = True
            break

    if very_urgent:
        if likely_cindy_alive:
            bid = min(budget, max(DAILY_SALARY * 1.05, bob_bid + 8.0))
        else:
            bid = min(budget, bob_bid + 6.0)
        return float(max(0.0, bid))

    if units <= 1:
        if urgent:
            bid = min(budget, max(DAILY_SALARY * 0.92, bob_bid + 4.0))
        else:
            bid = min(budget, DAILY_SALARY * 0.08)
        return float(max(0.0, bid))

    if units >= 2:
        if likely_cindy_alive:
            if urgent:
                bid = min(budget, max(bob_bid + 3.0, DAILY_SALARY * 0.92))
            else:
                bid = min(budget, max(bob_bid + 2.0, DAILY_SALARY * 0.9))
        else:
            if urgent:
                bid = min(budget, max(bob_bid + 2.0, DAILY_SALARY * 0.78))
            else:
                bid = min(budget, max(bob_bid + 1.5, DAILY_SALARY * 0.72))
    else:
        bid = min(budget, DAILY_SALARY * 0.5)

    if day >= 8 and hp >= 7 and no_water_days == 0 and units <= 1:
        bid = min(budget, DAILY_SALARY * 0.05)

    if budget < bid:
        bid = budget

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Collect alive opponents and their yesterday bids
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If no one is alive, bid conservatively
    if not alive_opps:
        return float(min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Use yesterday's max bid as a proxy for Cindy/Alex aggressiveness
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else 0.0

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))

    # Estimate how many units of water exist (not used directly for indexing, but for scaling)
    # supply is between 15 and 25; map to an intensity factor
    if supply <= MIN_SUPPLY:
        intensity = 0.85
    elif supply >= MAX_SUPPLY:
        intensity = 1.05
    else:
        intensity = 0.85 + (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) * (1.05 - 0.85)

    # If my hp is low, I must secure water: bid more aggressively.
    # If my hp is healthy, I can undercut slightly above last top bids.
    if my_hp <= 2.0:
        target = max(highest_prev_bid * 1.03, second_prev_bid + 6.0) * intensity
    elif my_hp <= 4.0:
        target = max(highest_prev_bid * 1.02, second_prev_bid + 4.0) * intensity
    else:
        # Healthy: bid a small premium over yesterday's max to try to win without burning budget
        target = max(highest_prev_bid + 2.0, second_prev_bid + 3.0) * intensity

    # Hard caps to avoid overspending
    # Keep within a fraction of budget; also avoid bidding far beyond typical daily salary scale.
    cap = my_budget
    # If Cindy spent ~147, bidding around 120-160 is plausible; cap at 1.8*salary to be safe.
    cap = min(cap, DAILY_SALARY * 1.8)

    bid = float(min(cap, max(0.0, target)))

    # If budget is extremely low, bid what we can
    if my_budget <= 5.0:
        return float(my_budget)

    # Ensure bid is at least a minimal competitive amount when supply is high
    min_competitive = 0.25 * DAILY_SALARY * intensity
    if bid < min_competitive and my_hp > 2.0:
        bid = min(cap, min_competitive)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    hp = my_status['hp']
    budget = my_status['budget']
    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive:
        return min(budget, DAILY_SALARY * 0.4)
    # Estimate opponent bids from yesterday
    bids = []
    for opp in alive.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bids.append(prev['bid'])
    # Set thresholds
    if hp <= 3:
        # urgent: outbid highest known (Cindy 147, but may be less)
        highest = max(bids) if bids else 147
        target = highest + 2
        return min(budget, max(target, DAILY_SALARY * 0.9))
    elif hp <= 5:
        # moderate: outbid Bob (around 60) but stay below Alex
        if bids:
            # assume Bob is the lowest among alive? use min bid plus safety
            low_bid = min(bids)
            target = low_bid + 1
        else:
            target = DAILY_SALARY * 0.5
        return min(budget, max(target, DAILY_SALARY * 0.5))
    else:
        # high HP: low bid
        return min(budget, DAILY_SALARY * 0.3)
